class AppLocalization {
  // Global language state ('EN' or 'HI')
  static final ValueNotifier<String> currentLang = ValueNotifier<String>('EN');

  static void toggleLanguage() {
    if (currentLang.value == 'EN') {
      currentLang.value = 'HI';
    } else {
      currentLang.value = 'EN';
    }
  }

  static void setLanguage(String lang) {
    if (lang == 'EN' || lang == 'HI') {
      currentLang.value = lang;
    }
  }

  // Helper method to get string based on current language
  static String get(String key) {
    final lang = currentLang.value;
    if (_dictionary.containsKey(key)) {
      return _dictionary[key]![lang] ?? key;
    }
    return key; // Fallback to key if not found
  }

